/// An AprilTag family. The tag is a `total` x `total` picture: black, with a one-cell white ring
/// (`width_at_border` cells wide, plus 2 unless `reversed`) and white where a bit of the code is set.
/// `bits[i]` is where the i-th most significant bit of a code goes, from the picture's corner.
pub struct April {
    pub name: &'static str,
    pub nbits: usize,
    pub width_at_border: i32,
    pub total: i32,
    pub reversed: bool,
    pub codes: &'static [u64],
    pub bits: &'static [(i8, i8)],
}

